/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
void shift(
    TreeNode*& root, stack<TreeNode*>& parents,
    function<TreeNode*(TreeNode*)> shift_0,
    function<TreeNode*(TreeNode*)> shift_1,
    function<bool(int, int)> cmp_0
) {
    if (!root) return;

    if (shift_1(root)) {
        parents.push(root);

        for (
            auto* root_next = shift_1(root);
            root_next;
            root_next = shift_0(root_next)
        ) {
            parents.push(root_next);
            root = root_next;
        }

        return;
    }

    auto target = root->val;

    // try going up
    while (root) {
        if (cmp_0(root->val, target)) break;

        if (parents.empty()) {
            root = nullptr;
            break;
        }
        root = parents.top();
        parents.pop();
    }
}

// Decrement root to the prev node
void prev(TreeNode*& root, stack<TreeNode*>& parents) {
    return shift(
        root, parents,
        [](TreeNode* n) { return n->right; },
        [](TreeNode* n) { return n->left; },
        [](int e0, int e1) { return e0 < e1; }
    );
}

// Increment root to the post node
void post(TreeNode*& root, stack<TreeNode*>& parents) {
    return shift(
        root, parents,
        [](TreeNode* n) { return n->left; },
        [](TreeNode* n) { return n->right; },
        [](int e0, int e1) { return e0 > e1; }
    );
}

int closest(int e0, int e1, int target) {
    if (abs(e0 - target) < abs(e1 - target)) {
        return e0;
    }
    return e1;
}

int bst(
    TreeNode* root,
    int target
) {
    if (!root) return -1;

    int ret = root->val;
    if (ret == target) return target; // base case

    auto root_next = target < root->val ? root->left : root->right;
    auto _ret = bst(root_next, target);
    if (_ret >= 0) {
        ret = closest(ret, _ret, target);
    }

    return ret;
}

TreeNode* bst_exact(
    TreeNode* root,
    stack<TreeNode*>& parents,
    int target
) {
    if (!root) return nullptr;

    int ret = root->val;
    if (ret == target) return root; // base case

    parents.push(root); // push the stack

    auto root_next = target < root->val ? root->left : root->right;
    return bst_exact(root_next, parents, target);
}

class Solution {
public:
    vector<int> closestKValues(TreeNode* root, double target, int k) {
        if (!root) return {};

        // We can probably get the nearest node and its
        // parent stack at the same time;
        // but I'm lazy.
        // So 2 searches are performed.
        const auto exact = bst(root, target);

        stack<TreeNode*> parents_prev;
        auto* n_prev = bst_exact(root, parents_prev, exact);
        auto parents_post = parents_prev;
        auto* n_post = n_prev;

        vector<int> ret_prev;
        ret_prev.reserve(k);
        for (auto i = 0; i < k; i += 1) {
            prev(n_prev, parents_prev);
            if (!n_prev) break;
            ret_prev.push_back(n_prev->val);
        }

        vector<int> ret_post;
        ret_post.reserve(k);
        for (auto i = 0; i < k; i += 1) {
            post(n_post, parents_post);
            if (!n_post) break;
            ret_post.push_back(n_post->val);
        }

        vector<pair<double, int>> ret;
        ret.reserve(k * 2 + 1);
        ret.emplace_back(abs(target - exact), exact);
        for (auto val : ret_prev) {
            ret.emplace_back(abs(target - val), val);
        }
        for (auto val : ret_post) {
            ret.emplace_back(abs(target - val), val);
        }
        sort(ret.begin(), ret.end());

        vector<int> ret_vec;
        ret_vec.reserve(k);
        for (auto i = 0; i < k; i += 1) {
            ret_vec.push_back(ret[i].second);
        }

        return ret_vec;
    }
};

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def closestKValues(self, root: TreeNode, target: float, k: int) -> List[int]:
        def dfs(root):
            if root is None:
                return
            dfs(root.left)
            if len(q) < k:
                q.append(root.val)
            else:
                if abs(root.val - target) >= abs(q[0] - target):
                    return
                q.popleft()
                q.append(root.val)
            dfs(root.right)

        q = deque()
        dfs(root)
        return list(q)

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {

    private List<Integer> ans;
    private double target;
    private int k;

    public List<Integer> closestKValues(TreeNode root, double target, int k) {
        ans = new LinkedList<>();
        this.target = target;
        this.k = k;
        dfs(root);
        return ans;
    }

    private void dfs(TreeNode root) {
        if (root == null) {
            return;
        }
        dfs(root.left);
        if (ans.size() < k) {
            ans.add(root.val);
        } else {
            if (Math.abs(root.val - target) >= Math.abs(ans.get(0) - target)) {
                return;
            }
            ans.remove(0);
            ans.add(root.val);
        }
        dfs(root.right);
    }
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    queue<int> q;
    double target;
    int k;

    vector<int> closestKValues(TreeNode* root, double target, int k) {
        this->target = target;
        this->k = k;
        dfs(root);
        vector<int> ans;
        while (!q.empty()) {
            ans.push_back(q.front());
            q.pop();
        }
        return ans;
    }

    void dfs(TreeNode* root) {
        if (!root) return;
        dfs(root->left);
        if (q.size() < k)
            q.push(root->val);
        else {
            if (abs(root->val - target) >= abs(q.front() - target)) return;
            q.pop();
            q.push(root->val);
        }
        dfs(root->right);
    }
};

/**
 * Definition for a binary tree node.
 * type TreeNode struct {
 *     Val int
 *     Left *TreeNode
 *     Right *TreeNode
 * }
 */
func closestKValues(root *TreeNode, target float64, k int) []int {
	var ans []int
	var dfs func(root *TreeNode)
	dfs = func(root *TreeNode) {
		if root == nil {
			return
		}
		dfs(root.Left)
		if len(ans) < k {
			ans = append(ans, root.Val)
		} else {
			if math.Abs(float64(root.Val)-target) >= math.Abs(float64(ans[0])-target) {
				return
			}
			ans = ans[1:]
			ans = append(ans, root.Val)
		}
		dfs(root.Right)
	}
	dfs(root)
	return ans
}

class Solution {
    public List<Integer> closestKValues(TreeNode root, double target, int k) {
        List<Integer> arr = new ArrayList<>();
        dfs(root, arr);

        Collections.sort(arr, new Comparator<Integer>() {
            @Override
            public int compare(Integer o1, Integer o2) {
                return Math.abs(o1 - target) < Math.abs(o2 - target) ? -1 : 1;
            }
        });

        return arr.subList(0, k);

    }

    public void dfs(TreeNode node, List<Integer> arr) {
        if (node == null) {
            return;
        }

        arr.add(node.val);
        dfs(node.left, arr);
        dfs(node.right, arr);
    }
}

class Solution {
    public List<Integer> closestKValues(TreeNode root, double target, int k) {
        Queue<Integer> heap = new PriorityQueue<>((a, b) -> Math.abs(a - target) > Math.abs(b - target) ? -1: 1);
        dfs(root, heap, k);

        return new ArrayList<>(heap);
    }

    public void dfs(TreeNode node, Queue<Integer> heap, int k) {
        if (node == null) {
            return;
        }

        heap.add(node.val);
        if (heap.size() > k) {
            heap.remove();
        }

        dfs(node.left, heap, k);
        dfs(node.right, heap, k);
    }
}

class Solution {
    public List<Integer> closestKValues(TreeNode root, double target, int k) {
        List<Integer> arr = new ArrayList<>();
        dfs(root, arr);

        int start = 0;
        double minDiff = Double.MAX_VALUE;

        for (int i = 0; i < arr.size(); i++) {
            if (Math.abs(arr.get(i) - target) < minDiff) {
                minDiff = Math.abs(arr.get(i) - target);
                start = i;
            }
        }

        int left = start;
        int right = start + 1;

        while (right - left - 1 < k) {
            // Be careful to not go out of bounds
            if (left < 0) {
                right += 1;
                continue;
            }

            if (right == arr.size() || Math.abs(arr.get(left) - target) <= Math.abs(arr.get(right) - target)) {
                left -= 1;
            } else {
                right += 1;
            }
        }

        return arr.subList(left + 1, right);
    }

    public void dfs(TreeNode node, List<Integer> arr) {
        if (node == null) {
            return;
        }

        dfs(node.left, arr);
        arr.add(node.val);
        dfs(node.right, arr);
    }
}

class Solution {
    public List<Integer> closestKValues(TreeNode root, double target, int k) {
        List<Integer> arr = new ArrayList<>();
        dfs(root, arr);

        int left = 0;
        int right = arr.size() - k;

        while (left < right) {
            int mid = (left + right) / 2;
            if (Math.abs(target - arr.get(mid + k)) < Math.abs(target - arr.get(mid))) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return arr.subList(left, left + k);
    }

    public void dfs(TreeNode node, List<Integer> arr) {
        if (node == null) {
            return;
        }

        dfs(node.left, arr);
        arr.add(node.val);
        dfs(node.right, arr);
    }
}

class Solution {
    public List<Integer> closestKValues(TreeNode root, double target, int k) {
        Deque<Integer> queue = new LinkedList<>();
        dfs(root, queue, k, target);
        return new ArrayList<>(queue);
    }

    public void dfs(TreeNode node, Deque<Integer> queue, int k, double target) {
        if (node == null) {
            return;
        }

        dfs(node.left, queue, k, target);
        queue.add(node.val);
        if (queue.size() > k) {
            if (Math.abs(target - queue.peekFirst()) < Math.abs(target - queue.peekLast())) {
                queue.removeLast();
                return;
            } else {
                queue.removeFirst();
            }
        }

        dfs(node.right, queue, k, target);
    }
}

